        "order": order,
        "is_solvable": solvable,
        "discriminant": discriminant,
    }


def assert_result(result, group, order, solvable, discriminant):
    """Assert the complete observable result and its value types."""
    assert isinstance(result, dict)
    assert set(result) == RESULT_KEYS
    assert result == expected(group, order, solvable, discriminant)
