        func_map = {
            'sin':   math.sin,
            'cos':   math.cos,
            'tan':   math.tan,
            'exp':   math.exp,
            'log':   math.log,
            'sqrt':  math.sqrt,
            'sq':    lambda x: x * x,
            'id':    lambda x: x,
            'abs':   abs,
        }
        if func_name not in func_map:
            raise ValueError(f"Unbekannte Funktion '{func_name}'. "
